    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        const player = { x: 0, y: 0 };
        const tiles = {};
        const inventory = { seeds: 5, crops: 0 };
        let day = 0;

        function drawPlayer() {
            ctx.fillStyle = 'green';
            ctx.fillRect(player.x, player.y, 10, 10);
        }

        function drawTiles() {
            for (const [key, tile] of Object.entries(tiles)) {
                ctx.fillStyle = tile.crop === 'seed' ? 'red' : 'green';
                ctx.fillRect(key.split(',')[0], key.split(',')[1], 10, 10);
            }
        }

        function drawInventory() {
            ctx.fillStyle = 'blue';
            ctx.fillText(`Seeds: ${inventory.seeds}`, 10, 20);
            ctx.fillText(`Crops: ${inventory.crops}`, 10, 40);
        }

        function drawDay() {
            ctx.fillStyle = 'yellow';
            ctx.fillText(`Day: ${day}`, 10, 60);
        }

        function update() {
            requestAnimationFrame(update);
            day++;
            drawDay();
        }

        function handleKeyDown(event) {
            switch (event.key) {
                case 'ArrowUp':
                    player.y -= 10;
                    break;
                case 'ArrowDown':
                    player.y += 10;
                    break;
                case 'ArrowLeft':
                    player.x -= 10;
                    break;
                case 'ArrowRight':
                    player.x += 10;
                    break;
                case 'p':
                    if (inventory.seeds > 0) {
                        tiles[`${player.x},${player.y}`] = { crop: 'seed', stage: 0 };
                        inventory.seeds--;
                    }
                    break;
                case 't':
                    // Implement time advancement logic here
                    break;
                case 'h':
                    // Implement crop harvesting logic here
                    break;
                case 's':
                    localStorage.setItem('game', JSON.stringify({ player, tiles, inventory, day }));
                    break;
            }
            drawPlayer();
            drawTiles();
            drawInventory();
        }

        canvas.addEventListener('keydown', handleKeyDown);
        update();

        window.game = { state: () => JSON.parse(JSON.stringify({ player, tiles, inventory, day })) };
    </script>
</body>
</html>
